contracts/CollateralBaseVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ICollateralBaseVault} from "./interfaces/ICollateralBaseVault/ICollateralBaseVault.sol";

/**
 * @title Base CollateralVault 6022
 * @author 6022
 * @notice This contract is a abstract contract for CollateralRewardPoolLifetimeVault and CollateralVault.
 */
abstract contract CollateralBaseVault is ICollateralBaseVault {
    // ----------------- VARIABLES ----------------- //
    /// @notice Indicates if the contract is deposited
    bool public isDeposited;

    /// @notice Indicates if the contract is withdrawn
    bool public isWithdrawn;

    /// @notice Amount wanted in the deposit of the protocol token
    uint256 public wantedAmount;

    /// @notice Reward pool
    address public rewardPool;

    constructor(address _rewardPool, uint256 _wantedAmount) {
        isDeposited = false;
        isWithdrawn = false;

        rewardPool = _rewardPool;
        wantedAmount = _wantedAmount;
    }

    // ----------------- MODIFIERS ----------------- //
    modifier onlyWhenDeposited() {
        if (!isDeposited) {
            revert NotDeposited();
        }
        _;
    }

    modifier onlyWhenNotDeposited() {
        if (isDeposited) {
            revert AlreadyDeposited();
        }
        _;
    }

    modifier onlyWhenNotWithdrawn() {
        if (isWithdrawn) {
            revert AlreadyWithdrawn();
        }
        _;
    }
}

contracts/CollateralController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

import {ICollateralController} from "./interfaces/ICollateralController/ICollateralController.sol";
import {ICollateralRewardPoolStates} from "./interfaces/ICollateralRewardPool/ICollateralRewardPoolStates.sol";

/**
 * @title CollateralController 6022
 * @author 6022
 * @notice This contract aims to register all vaults and reward pools.
 */
contract CollateralController is AccessControl, ICollateralController {
    // ----------------- CONST ----------------- //
    /// @notice The role that allows an account to use admin functions
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice The role that allows factories to use factory functions
    bytes32 public constant FACTORY_ROLE = keccak256("FACTORY_ROLE");

    // ----------------- VARIABLES ----------------- //
    /// @notice List of all vaults
    address[] public allVaults;

    /// @notice List of all reward pools
    address[] public allRewardPools;

    address public vaultDescriptor;

    /// @notice Mapping of all reward pools
    mapping(address => bool) public isRewardPool;

    constructor() {
        _grantRole(ADMIN_ROLE, msg.sender);
        emit AdminAdded(msg.sender);
    }

    // ----------------- MODIFIERS ----------------- //
    modifier onlyRewardPool() {
        if (!isRewardPool[msg.sender]) {
            revert NotRewardPool();
        }
        _;
    }

    // ----------------- FUNCS ----------------- //
    function allVaultsLength() external view returns (uint) {
        return allVaults.length;
    }

    function allRewardPoolsLength() external view returns (uint) {
        return allRewardPools.length;
    }

    function pushVault(address _vault) external onlyRewardPool {
        allVaults.push(_vault);
        emit VaultPushed(_vault);
    }

    function pushRewardPool(
        address _rewardPool
    ) external onlyRole(FACTORY_ROLE) {
        allRewardPools.push(_rewardPool);
        isRewardPool[_rewardPool] = true;
        emit RewardPoolPushed(_rewardPool);
    }

    function updateVaultDescriptor(
        address _vaultDescriptor
    ) external onlyRole(ADMIN_ROLE) {
        vaultDescriptor = _vaultDescriptor;
        emit VaultDescriptorUpdated(_vaultDescriptor);
    }

    function addFactory(address account) external onlyRole(ADMIN_ROLE) {
        _grantRole(FACTORY_ROLE, account);
        emit FactoryAdded(account);
    }

    function removeFactory(address account) external onlyRole(ADMIN_ROLE) {
        _revokeRole(FACTORY_ROLE, account);
        emit FactoryRemoved(account);
    }

    function addAdmin(address account) external onlyRole(ADMIN_ROLE) {
        _grantRole(ADMIN_ROLE, account);
        emit AdminAdded(account);
    }

    function removeAdmin(address account) external onlyRole(ADMIN_ROLE) {
        _revokeRole(ADMIN_ROLE, account);
        emit AdminRemoved(account);
    }

    function getRewardPoolsByCreator(
        address creator
    ) external view returns (address[] memory) {
        uint256 counter = 0;

        for (uint256 i = 0; i < allRewardPools.length; i++) {
            ICollateralRewardPoolStates rewardPool = ICollateralRewardPoolStates(allRewardPools[i]);
            if (rewardPool.creator() == creator) {
                counter++;
            }
        }

        address[] memory creatorRewardPool = new address[](counter);
        uint256 index = 0;

        for (uint256 i = 0; i < allRewardPools.length; i++) {
            ICollateralRewardPoolStates rewardPool = ICollateralRewardPoolStates(allRewardPools[i]);
            if (rewardPool.creator() == creator) {
                creatorRewardPool[index] = allRewardPools[i];
                index++;
            }
        }

        return creatorRewardPool;
    }

    function getVaultsByOwner(
        address owner
    ) external view returns (address[] memory) {
        uint256 counter = 0;

        for (uint256 i = 0; i < allVaults.length; i++) {
            IERC721 vault = IERC721(allVaults[i]);
            if (vault.balanceOf(owner) > 0) {
                counter++;
            }
        }

        address[] memory ownerVault = new address[](counter);
        uint256 index = 0;

        for (uint256 i = 0; i < allVaults.length; i++) {
            IERC721 vault = IERC721(allVaults[i]);
            if (vault.balanceOf(owner) > 0) {
                ownerVault[index] = allVaults[i];
                index++;
            }
        }

        return ownerVault;
    }
}

contracts/CollateralRewardPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CollateralVault} from "./CollateralVault.sol";
import {VaultStorageEnum} from "./enums/VaultStorageEnum.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {CollateralRewardPoolLifetimeVault} from "./CollateralRewardPoolLifetimeVault.sol";
import {ICollateralRewardPool} from "./interfaces/ICollateralRewardPool/ICollateralRewardPool.sol";
import {ICollateralBaseVaultStates} from "./interfaces/ICollateralBaseVault/ICollateralBaseVaultStates.sol";
import {ICollateralControllerRewardPoolActions} from "./interfaces/ICollateralController/ICollateralControllerRewardPoolActions.sol";

/**
 * @title Reward Pool
 * @author 6022
 * @notice This contract is created by a Factory contract.
 * It is used to manage a pool of vaults and distribute rewards to them.
 * Only the creator of the pool can create vaults and thus pay the fees.
 */
contract CollateralRewardPool is Ownable, ICollateralRewardPool {
    // ----------------- CONST ----------------- //
    uint8 public constant FEES_PERCENT = 2;

    // ----------------- VARIABLES ----------------- //
    /// @notice List of all vaults related to this reward pool
    address[] public allVaults;

    /// @notice Protocol token
    IERC20 public protocolToken;

    /// @notice CollateralController 6022
    address public controller;

    /// @notice Lifetime vault that will act as default fee collector and serve as reward pool state.
    CollateralRewardPoolLifetimeVault public lifetimeVault;

    /// @notice Mapping of all vaults
    mapping(address => bool) public isVault;

    /// @notice Mapping of all collected rewards
    mapping(address => uint256) public collectedRewards;

    /// @notice Mapping of all vault weight in the reward mechanism
    mapping(address => uint256) public vaultsRewardWeight;

    constructor(
        address _owner,
        address _controllerAddress,
        address _protocolTokenAddress
    ) Ownable(_owner) {
        protocolToken = IERC20(_protocolTokenAddress);
        controller = _controllerAddress;
    }

    // ----------------- MODIFIERS ----------------- //
    modifier onlyVault() {
        if (!isVault[msg.sender]) revert CallerNotVault();
        _;
    }

    modifier onlyWhenLifetimeVaultDoesNotExist() {
        if (address(lifetimeVault) != address(0))
            revert LifeTimeVaultAlreadyExist();
        _;
    }

    modifier onlyWhenLifetimeVaultExist() {
        if (address(lifetimeVault) == address(0))
            revert LifeTimeVaultDoesNotExist();
        _;
    }

    modifier onlyWhenLifetimeVaultIsRewardable() {
        if (!lifetimeVault.isRewardable())
            revert LifeTimeVaultIsNotRewardable();
        _;
    }

    modifier onlyWhenLifetimeVaultIsNotRewardable() {
        if (lifetimeVault.isRewardable()) revert LifeTimeVaultIsRewardable();
        _;
    }

    // ----------------- FUNCS ----------------- //
    function creator() external view override returns (address) {
        return owner();
    }

    function allVaultsLength() external view returns (uint) {
        return allVaults.length;
    }

    /// @notice This method will create the lifetime vault and deposit the protocol token in it. It will allow to create standard vaults.
    function createLifetimeVault(
        uint256 _lifetimeVaultAmount
    ) external onlyWhenLifetimeVaultDoesNotExist {
        uint256 lifetimeVaultFees = _computeFeesFromCollateralWithFees(
            _lifetimeVaultAmount
        );
        uint256 finalLifetimeVaultCollateralAmount = _lifetimeVaultAmount -
            lifetimeVaultFees;

        lifetimeVault = new CollateralRewardPoolLifetimeVault(
            owner(),
            address(this),
            finalLifetimeVaultCollateralAmount,
            address(protocolToken)
        );

        allVaults.push(address(lifetimeVault));
        isVault[address(lifetimeVault)] = true;

        emit VaultCreated(address(lifetimeVault));
    }

    /// @notice This method will deposit the protocol token in the lifetime vault and thus start the reward mechanism.
    function depositToLifetimeVault() external onlyWhenLifetimeVaultExist {
        uint256 lifetimeVaultAmount = lifetimeVault.wantedAmount();

        protocolToken.approve(address(lifetimeVault), lifetimeVaultAmount);
        lifetimeVault.deposit();

        uint256 lifetimeVaultFees = _computeFeesFromCollateral(
            lifetimeVaultAmount
        );

        // Reward pool already own the fees
        vaultsRewardWeight[address(lifetimeVault)] += lifetimeVaultFees;
        _updateRewards(lifetimeVaultFees);
    }

    /// @notice This method will withdraw the protocol token dust from the pool
    function collectDust()
        external
        onlyOwner
        onlyWhenLifetimeVaultExist
        onlyWhenLifetimeVaultIsNotRewardable
    {
        // Here there is no more rewardable vaults but some vaults can still have rewards (because not yet withdrawn).
        // Those rewards needs to stay in the pool to be harvested when final users will withdraw their collateral in vaults.
        uint256 remainingRewards = _totalCollectedRewards();
        uint256 balance = protocolToken.balanceOf(address(this));

        uint256 dust = balance - remainingRewards;

        if (dust == 0) {
            revert NoDustToCollect();
        }

        protocolToken.transfer(owner(), dust);

        emit DustCollected(dust);
    }

    /// @notice This method will create a new vault.
    function createVault(
        string memory _name,
        string memory _image,
        uint256 _lockedUntil,
        uint256 _wantedAmount,
        address _wantedTokenAddress,
        VaultStorageEnum _storageType,
        uint256 _backedValueProtocolToken
    )
        public
        onlyOwner
        onlyWhenLifetimeVaultExist
        onlyWhenLifetimeVaultIsRewardable
    {
        if (block.timestamp + 1 minutes > _lockedUntil) {
            revert LockedUntilTooShort();
        }

        // For people who try to cheat by putting a different backed value in case of protocol token collateral
        // We override the passed parameter using the _wantedAmount
        if (_wantedTokenAddress == address(protocolToken)) {
            _backedValueProtocolToken = _wantedAmount;
        }

        uint256 _protocolTokenFees = _computeFeesFromCollateral(
            _backedValueProtocolToken
        );

        // Here there is at least the lifetime vault that will be able to take the rewards (onlyWhenLifetimeVaultIsRewardable)
        // The lifetime vault is own by the owner of this smart contract indirectly
        // And only the owner can create a vault (and thus pay fees)
        // So the fees that pay the owner will finally go back to him (in case of only the lifetime vault)
        protocolToken.transferFrom(
            msg.sender,
            address(this),
            _protocolTokenFees
        );
        _updateRewards(_protocolTokenFees);

        CollateralVault vault = new CollateralVault(
            msg.sender,
            _name,
            _image,
            _lockedUntil,
            _wantedAmount,
            address(this),
            _wantedTokenAddress,
            _storageType
        );

        allVaults.push(address(vault));
        isVault[address(vault)] = true;
        vaultsRewardWeight[address(vault)] += _protocolTokenFees;

        ICollateralControllerRewardPoolActions(controller).pushVault(address(vault));

        emit VaultCreated(address(vault));
    }

    /// @notice Harvest rewards of a closed vault (in case of late withdraw)
    /// @param to Address of the withdrawer
    function harvestRewards(address to) external onlyVault {
        uint256 valueToHarvest = collectedRewards[msg.sender];
        collectedRewards[msg.sender] = 0;

        protocolToken.transfer(to, valueToHarvest);

        emit Harvested(msg.sender, valueToHarvest);
    }

    /// @notice Reinvest rewards of a closed vault into rewardable vaults (in case of early withdraw)
    function reinvestRewards()
        external
        onlyVault
        onlyWhenLifetimeVaultIsRewardable
    {
        uint256 valueToReinvest = collectedRewards[msg.sender];
        collectedRewards[msg.sender] = 0;

        _updateRewards(valueToReinvest);

        emit Reinvested(msg.sender, valueToReinvest);
    }

    /// @notice Count every rewardable vaults without the lifetime vault
    function countRewardableVaults() public view returns (uint256) {
        uint256 count = 0;

        for (uint i = 0; i < allVaults.length; i++) {
            ICollateralBaseVaultStates vault = ICollateralBaseVaultStates(allVaults[i]);
            if (vault.isRewardable()) {
                count++;
            }
        }

        return count;
    }

    /// @notice Method to inject new rewards to rewardable vaults
    /// @param amount Amount of rewards that need to be injected into rewardable vaults
    function _updateRewards(uint256 amount) internal {
        uint256 totalRewardableRewardWeight = _totalRewardableRewardWeight();
        if (totalRewardableRewardWeight == 0) return; // No vaults to reward and avoid division by zero

        address[] memory rewardableVaults = _rewardableVaults();

        uint256 remainingRewardsToDistribute = amount;

        // The "rewardableVaults" array is not sorted by reward weight to not increase gas cost
        // In case of amountToDistribute == 0, the oldest vaults will be rewarded first
        // Not unfair because of the tiny amount to distribute

        // Distribute rewards
        for (uint256 i = 0; i < rewardableVaults.length; i++) {
            address vaultAddress = rewardableVaults[i];
            uint256 amountToDistribute = (amount *
                vaultsRewardWeight[vaultAddress]) / totalRewardableRewardWeight;

            if (amountToDistribute == 0 && remainingRewardsToDistribute > 0) {
                amountToDistribute = 1;
            }

            // As we don't sort "rewardableVaults" and due to the previous "if" statement
            // We must verify that "amountToDistribute" is not greater than "remainingRewardsToDistribute"
            // In order to be sure that the reward pool doesn't allow more token than it has to distribute
            if (amountToDistribute > remainingRewardsToDistribute) {
                amountToDistribute = remainingRewardsToDistribute;
            }

            remainingRewardsToDistribute -= amountToDistribute;
            collectedRewards[vaultAddress] += amountToDistribute;
        }
    }

    /// @notice Total reward weight in the pool (only rewardable vaults)
    function _totalRewardableRewardWeight() internal view returns (uint256) {
        uint256 totalRewardableRewardWeight = 0;

        for (uint i = 0; i < allVaults.length; i++) {
            ICollateralBaseVaultStates vault = ICollateralBaseVaultStates(allVaults[i]);
            if (vault.isRewardable()) {
                totalRewardableRewardWeight += vaultsRewardWeight[
                    address(vault)
                ];
            }
        }

        return totalRewardableRewardWeight;
    }

    /// @notice List of rewardable vaults
    function _rewardableVaults() internal view returns (address[] memory) {
        uint256 count = countRewardableVaults();
        address[] memory rewardableVaults = new address[](count);

        uint256 index = 0;
        for (uint i = 0; i < allVaults.length; i++) {
            ICollateralBaseVaultStates vault = ICollateralBaseVaultStates(allVaults[i]);
            if (vault.isRewardable()) {
                rewardableVaults[index] = address(vault);
                index++;
            }
        }

        return rewardableVaults;
    }

    /// @notice Total collected rewards in the pool
    function _totalCollectedRewards() internal view returns (uint256) {
        uint256 totalCollectedRewards = 0;

        for (uint i = 0; i < allVaults.length; i++) {
            totalCollectedRewards += collectedRewards[allVaults[i]];
        }

        return totalCollectedRewards;
    }

    function _computeFeesFromCollateral(
        uint256 _collateral
    ) internal pure returns (uint256) {
        return (_collateral * FEES_PERCENT) / 100;
    }

    function _computeFeesFromCollateralWithFees(
        uint256 _collateralWithFees
    ) internal pure returns (uint256) {
        uint256 collateralWithFeesBy100 = _collateralWithFees * 100;
        uint256 feesBy100 = (collateralWithFeesBy100 * FEES_PERCENT) /
            (100 + FEES_PERCENT);

        return feesBy100 / 100;
    }
}

contracts/CollateralRewardPoolFactory.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {CollateralRewardPool} from "./CollateralRewardPool.sol";
import {ICollateralControllerHelpers} from "./interfaces/ICollateralController/ICollateralControllerHelpers.sol";
import {ICollateralRewardPoolFactory} from "./interfaces/ICollateralRewardPoolFactory/ICollateralRewardPoolFactory.sol";
import {ICollateralControllerRewardPoolFactoryActions} from "./interfaces/ICollateralController/ICollateralControllerRewardPoolFactoryActions.sol";

/**
 * @title Reward Pool Factory 6022
 * @author 6022
 * @notice This contract is used to create reward pools.
 */
contract CollateralRewardPoolFactory is ICollateralRewardPoolFactory {
    // ----------------- VARIABLES ----------------- //
    /// @notice CollateralController 6022 address
    address public controller;

    /// @notice Protocol token address
    IERC20 public protocolTokenAddress;

    constructor(address _controllerAddress, address _protocolTokenAddress) {
        controller = _controllerAddress;
        protocolTokenAddress = IERC20(_protocolTokenAddress);
    }

    // ----------------- MODIFIERS ----------------- //
    modifier onlyWhenSenderDoesNotHaveRewardPool() {
        address[] memory alreadyCreatedRewardPools = ICollateralControllerHelpers(controller)
            .getRewardPoolsByCreator(msg.sender);

        if (alreadyCreatedRewardPools.length > 0) {
            revert AlreadyCreatedRewardPool();
        }

        _;
    }

    // ----------------- FUNCS ----------------- //
    function createRewardPool(
        uint256 _lifetimeVaultAmount
    ) external onlyWhenSenderDoesNotHaveRewardPool {
        CollateralRewardPool rewardPool = new CollateralRewardPool(
            msg.sender,
            controller,
            address(protocolTokenAddress)
        );

        rewardPool.createLifetimeVault(_lifetimeVaultAmount);

        protocolTokenAddress.transferFrom(
            msg.sender,
            address(rewardPool),
            _lifetimeVaultAmount
        );
        rewardPool.depositToLifetimeVault();

        ICollateralControllerRewardPoolFactoryActions(controller).pushRewardPool(address(rewardPool));
        emit RewardPoolCreated(address(rewardPool));
    }
}

contracts/CollateralRewardPoolLifetimeVa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {CollateralBaseVault} from "./CollateralBaseVault.sol";
import {ICollateralRewardPoolStates} from "./interfaces/ICollateralRewardPool/ICollateralRewardPoolStates.sol";
import {ICollateralRewardPoolVaultActions} from "./interfaces/ICollateralRewardPool/ICollateralRewardPoolVaultActions.sol";
import {ICollateralRewardPoolLifetimeVault} from "./interfaces/ICollateralRewardPoolLifetimeVault/ICollateralRewardPoolLifetimeVault.sol";

/**
 * @title Reward Pool Lifetime CollateralVault
 * @author 6022
 * @notice This contract is only created at a reward pool creation.
 * It will be used as a default vault for the rewards in case there is no rewardable vault in the pool.
 * The collateral and the rewards for this contract are owned by the creator of the reward pool.
 */
contract CollateralRewardPoolLifetimeVault is Ownable, CollateralBaseVault, ICollateralRewardPoolLifetimeVault {
    // ----------------- VARIABLES ----------------- //
    /// @notice Contract of the protocol token
    IERC20 public protocolToken;

    constructor(
        address _owner,
        address _rewardPool,
        uint256 _wantedAmount,
        address _protocolToken
    ) Ownable(_owner) CollateralBaseVault(_rewardPool, _wantedAmount) {
        isDeposited = false;
        isWithdrawn = false;

        protocolToken = IERC20(_protocolToken);
    }

    // ----------------- MODIFIERS ----------------- //
    modifier onlyWhenLastVaultInPool() {
        // Check if there is only one rewardable vault left (this one, because of onlyWhenNotWithdrawn)
        if (ICollateralRewardPoolStates(rewardPool).countRewardableVaults() != 1)
            revert RemainingRewardableVaults();
        _;
    }

    modifier onlyRewardPool() {
        if (address(rewardPool) != _msgSender()) {
            revert OwnableUnauthorizedAccount(_msgSender());
        }
        _;
    }

    // ----------------- FUNCS ----------------- //
    function deposit() external override onlyRewardPool onlyWhenNotDeposited {
        protocolToken.transferFrom(msg.sender, address(this), wantedAmount);

        isDeposited = true;
        emit Deposited(_msgSender(), wantedAmount);
    }

    function withdraw()
        external
        override
        onlyOwner
        onlyWhenDeposited
        onlyWhenNotWithdrawn
        onlyWhenLastVaultInPool
    {
        protocolToken.transfer(_msgSender(), wantedAmount);

        ICollateralRewardPoolVaultActions(rewardPool).harvestRewards(_msgSender());

        isWithdrawn = true;
        emit Withdrawn(_msgSender(), wantedAmount);
    }

    function isRewardable() external view override returns (bool) {
        return isDeposited && !isWithdrawn;
    }
}

contracts/CollateralVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {CollateralBaseVault} from "./CollateralBaseVault.sol";
import {VaultOverview} from "./structs/VaultOverview.sol";
import {VaultStorageEnum} from "./enums/VaultStorageEnum.sol";
import {ICollateralTokenOperation} from "./interfaces/ICollateralTokenOperation.sol";
import {ICollateralVault} from "./interfaces/ICollateralVault/ICollateralVault.sol";
import {ICollateralControllerStates} from "./interfaces/ICollateralController/ICollateralControllerStates.sol";
import {ICollateralRewardPoolStates} from "./interfaces/ICollateralRewardPool/ICollateralRewardPoolStates.sol";
import {ICollateralRewardPoolVaultActions} from "./interfaces/ICollateralRewardPool/ICollateralRewardPoolVaultActions.sol";
import {ICollateralVaultDescriptorActions} from "./interfaces/ICollateralVaultDescriptor/ICollateralVaultDescriptorActions.sol";

/**
 * @title CollateralVault
 * @author 6022
 * @notice This contract is created inside a reward pool.
 * It will be used as a vault for every users to deposit a collateral for a reward pool owner.
 */
contract CollateralVault is ERC721, CollateralBaseVault, ReentrancyGuard, ICollateralVault {
    // ----------------- CONST ----------------- //
    uint public constant MAX_TOKENS = 3;
    uint public constant WITHDRAW_NFTS_EARLY = 2;
    uint public constant WITHDRAW_NFTS_LATE = 1;

    // ----------------- VARIABLES ----------------- //
    /// @notice Creator of the contract
    address public creator;

    /// @notice Timestamp until the contract is locked (before = 2 NFT to withdraw, after = 1 NFT to withdraw)
    uint256 public lockedUntil;

    /// @notice Vault image (IPFS hash/path)
    string public image;

    /// @notice Indicates the deposit timestamp
    uint256 public depositTimestamp;

    /// @notice Indicates the withdraw timestamp
    uint256 public withdrawTimestamp;

    /// @notice Indicates the creation timestamp
    uint256 public creationTimestamp;

    /// @notice ERC20 or ERC721 token address
    address public wantedTokenAddress;

    /// @notice Indicate if the 'wantedTokenAddress' is a ERC20 or ERC721 token
    VaultStorageEnum public storageType;

    constructor(
        address _creator,
        string memory _name,
        string memory _image,
        uint256 _lockedUntil,
        uint256 _wantedAmount,
        address _rewardPoolAddress,
        address _wantedTokenAddress,
        VaultStorageEnum _storageType
    ) ERC721(_name, "6022") CollateralBaseVault(_rewardPoolAddress, _wantedAmount) {
        creator = _creator;
        image = _image;
        lockedUntil = _lockedUntil;
        storageType = _storageType;
        creationTimestamp = block.timestamp;
        wantedTokenAddress = _wantedTokenAddress;

        // Mint tokens to the creator (transaction signer)
        for (uint i = 1; i <= MAX_TOKENS; i++) {
            _mint(address(_creator), i);
        }
    }

    function deposit() public onlyWhenNotDeposited nonReentrant {
        if (balanceOf(msg.sender) == 0) {
            revert NotEnoughNFTToDeposit();
        }

        if (block.timestamp > lockedUntil) {
            revert TooLateToDeposit();
        }

        ICollateralTokenOperation wantedToken = ICollateralTokenOperation(wantedTokenAddress);
        wantedToken.transferFrom(msg.sender, address(this), wantedAmount);

        isDeposited = true;
        depositTimestamp = block.timestamp;

        emit Deposited(msg.sender, wantedAmount);
    }

    /// @notice Once the vault is withdrawn, the vault is considered as a "dead" smart contract.
    function withdraw()
        public
        onlyWhenDeposited
        onlyWhenNotWithdrawn
        nonReentrant
    {
        uint256 requiredNFTs = getRequiredNftsToWithdraw();
        if (requiredNFTs > balanceOf(msg.sender)) {
            revert NotEnoughNFTToWithdraw();
        }

        if (storageType == VaultStorageEnum.ERC721) {
            IERC721 wantedToken = IERC721(wantedTokenAddress);

            wantedToken.transferFrom(address(this), msg.sender, wantedAmount);
            emit Withdrawn(msg.sender, wantedAmount);
        } else {
            IERC20 wantedToken = IERC20(wantedTokenAddress);
            uint256 balance = wantedToken.balanceOf(address(this));

            wantedToken.transfer(msg.sender, balance);
            emit Withdrawn(msg.sender, balance);
        }

        // We put "isWithdrawn" to true to put the vault as non rewardable
        // As the vault will be considered as a "dead" smart contract
        // We don't want to reward it anymore via other contracts creation or via the reinvest method
        isWithdrawn = true;
        withdrawTimestamp = block.timestamp;

        if (requiredNFTs == WITHDRAW_NFTS_LATE) {
            ICollateralRewardPoolVaultActions(rewardPool).harvestRewards(msg.sender);
        } else {
            ICollateralRewardPoolVaultActions(rewardPool).reinvestRewards();
        }
    }

    function getRequiredNftsToWithdraw() public view returns (uint256) {
        return
            block.timestamp < lockedUntil
                ? WITHDRAW_NFTS_EARLY
                : WITHDRAW_NFTS_LATE;
    }

    function isRewardable() external view returns (bool) {
        return lockedUntil > block.timestamp && isDeposited && !isWithdrawn;
    }

    function vaultOverview() external view returns (VaultOverview memory) {
        string memory wantedTokenSymbol = "N/A";
        (bool success, bytes memory data) = wantedTokenAddress.staticcall(
            abi.encodeWithSignature("symbol()")
        );
        if (success) {
            wantedTokenSymbol = abi.decode(data, (string));
        } else {
            (success, data) = wantedTokenAddress.staticcall(
                abi.encodeWithSignature("name()")
            );
            if (success) {
                wantedTokenSymbol = abi.decode(data, (string));
            }
        }

        uint8 wantedTokenDecimals = 0;
        (success, data) = wantedTokenAddress.staticcall(
            abi.encodeWithSignature("decimals()")
        );
        if (success) {
            wantedTokenDecimals = abi.decode(data, (uint8));
        }

        ICollateralTokenOperation wantedToken = ICollateralTokenOperation(wantedTokenAddress);
        ICollateralRewardPoolStates rewardPoolStates = ICollateralRewardPoolStates(
            rewardPool
        );

        return
            VaultOverview({
                name: name(),
                creator: creator,
                isDeposited: isDeposited,
                isWithdrawn: isWithdrawn,
                lockedUntil: lockedUntil,
                storageType: storageType,
                wantedAmount: wantedAmount,
                depositTimestamp: depositTimestamp,
                withdrawTimestamp: withdrawTimestamp,
                creationTimestamp: creationTimestamp,
                wantedTokenSymbol: wantedTokenSymbol,
                rewardPoolAddress: address(rewardPool),
                wantedTokenAddress: wantedTokenAddress,
                wantedTokenDecimals: wantedTokenDecimals,
                rewardWeight: rewardPoolStates.vaultsRewardWeight(address(this)),
                balanceOfWantedToken: wantedToken.balanceOf(address(this)),
                collectedRewards: rewardPoolStates.collectedRewards(address(this)),
                backedValueProtocolToken: (rewardPoolStates.vaultsRewardWeight(
                    address(this)
                ) * 100) / rewardPoolStates.FEES_PERCENT()
            });
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override
        returns (string memory)
    {
        _requireOwned(tokenId);

        address controllerAddress = ICollateralRewardPoolStates(rewardPool)
            .controller();
        address vaultDescriptorAddress = ICollateralControllerStates(controllerAddress)
            .vaultDescriptor();

        return ICollateralVaultDescriptorActions(vaultDescriptorAddress).buildTokenURI(
            address(this),
            tokenId
        );
    }
}

